/// <summary>
/// MPJ-37288
/// </summary>
public void initValue()
{
    super();
    METCBCTInvoiceHeaderTable  metCBCTInvoiceHeaderTable = element.args().record();
    VendInvoiceHeaderTable.VendorAccount            = metCBCTInvoiceHeaderTable.VendorAccount;
    VendInvoiceHeaderTable.VendorInvoiceNumber      = metCBCTInvoiceHeaderTable.TaxInvoiceNum;
    VendInvoiceHeaderTable.CustomerAccount          = metCBCTInvoiceHeaderTable.CustomerAccount;
    VendInvoiceHeaderTable.VendInvoiceAmtInclGST    = metCBCTInvoiceHeaderTable.VendInvoiceAmtInclGST;
    VendInvoiceHeaderTable.VendInvoiceGSTAmount     = metCBCTInvoiceHeaderTable.VendInvoiceGSTAmount;
    VendInvoiceHeaderTable.DocumentDate             = metCBCTInvoiceHeaderTable.DocumentDate;
}

        /// <summary>
        ///
        /// </summary>
        public void initValue()
        {
            METCBCTVendInvoiceLine metCBCTVendInvoiceLine;
            select maxof(LineNum) from metCBCTVendInvoiceLine
            where metCBCTVendInvoiceLine.Number == VendInvoiceHeaderTable.Number;
            VendInvoiceLine.LineNum = metCBCTVendInvoiceLine.LineNum+1;
            super();

        }

/// <summary>
/// MPJ-37288
/// </summary>
/// <param name = "_formReferenceControl"></param>
/// <returns>ret</returns>
public Common resolveReference(FormReferenceControl _formReferenceControl)
{
    Common ret;
    EcoResCategoryHierarchyRole ecoResCategoryHierarchyRole;
    select firstonly ecoResCategoryHierarchyRole
        where ecoResCategoryHierarchyRole.NamedCategoryHierarchyRole == EcoResCategoryNamedHierarchyRole::Retail;
    EcoResCategoryHierarchy     categoryHierarchy  = EcoResCategoryHierarchy::find(ecoResCategoryHierarchyRole.CategoryHierarchy);                
    
    ret = EcoResCategory::lookupCategoryHierarchy(_formReferenceControl,categoryHierarchy);
    

    return ret;
}

/// <summary>
/// MPJ-37288
/// </summary>
/// <param name = "_formReferenceControl"></param>
/// <returns>ret</returns>
public Common lookupReference(FormReferenceControl _formReferenceControl)
{
    Common ret;
    EcoResCategoryHierarchyRole ecoResCategoryHierarchyRole;
    select firstonly ecoResCategoryHierarchyRole
        where ecoResCategoryHierarchyRole.NamedCategoryHierarchyRole == EcoResCategoryNamedHierarchyRole::Retail;
    EcoResCategoryHierarchy     categoryHierarchy  = EcoResCategoryHierarchy::find(ecoResCategoryHierarchyRole.CategoryHierarchy);
    
    ret = EcoResCategory::lookupCategoryHierarchy(_formReferenceControl,categoryHierarchy);
    return ret;
}
